(function(){'use strict';function initHamburgerMenu(){const hamburger=document.getElementById('menuToggle');const menu=document.getElementById('hamburgerMenu');if(!hamburger || !menu)return;hamburger.addEventListener('click',(e)=>{e.preventDefault();e.stopPropagation();menu.classList.toggle('active');});document.addEventListener('click',(e)=>{if(!menu.contains(e.target)&& !hamburger.contains(e.target)){menu.classList.remove('active');}});document.addEventListener('keydown',(e)=>{if(e.key==='Escape'){menu.classList.remove('active');}});}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initHamburgerMenu);}else{initHamburgerMenu();}})();